htmlform.script:
jq(document).ready(function() {
    // Collapse all sections on load
    jq(".collapsible-content").hide();

    // Toggle content when header is tapped
    jq(".sectionHeader").click(function() {
        jq(this).toggleClass("expanded");
        jq(this).next(".collapsible-content").slideToggle("fast");
    });

    var HISTORY_SELECTOR = '.order-field-widget.order-clinicalHistory textarea';
    var MAX_HISTORY_LENGTH = 512;
    // From this many characters left, the counter warns that the limit is close
    var HISTORY_WARNING_LEFT = 50;

    // Clinical history shared with the other tests while a "same clinical history" box is ticked, else null
    var sharedHistory = null;

    // The order widget clones a hidden template (id ending in "_template") for each test that is added
    var isTemplate = function(element) {
        var orderForm = jq(element).closest('[id*="_template"]');
        return orderForm.length > 0 && /_template$/.test(orderForm.attr('id'));
    };

    var getOrderForm = function(element) {
        return jq(element).closest('[id*="_template"]');
    };

    var getHistoryFields = function() {
        return jq(HISTORY_SELECTOR).filter(function() { return !isTemplate(this); });
    };

    // Fill the shared history into the other tests, unless the doctor already typed something different there
    var applySharedHistory = function(previousValue) {
        if (sharedHistory === null) {
            return;
        }
        getHistoryFields().each(function() {
            var field = jq(this);
            var current = jq.trim(field.val());
            if (current === '' || (previousValue !== undefined && current === jq.trim(previousValue))) {
                field.val(sharedHistory);
            }
        });
    };

    // The nearest other test with a clinical history: the closest one above, otherwise the closest one below
    var findHistoryToCopy = function(field) {
        var fields = getHistoryFields().toArray();
        var index = fields.indexOf(field[0]);
        for (var i = index - 1; i >= 0; i--) {
            if (jq.trim(jq(fields[i]).val()) !== '') {
                return jq(fields[i]);
            }
        }
        for (var j = index + 1; j < fields.length; j++) {
            if (jq.trim(jq(fields[j]).val()) !== '') {
                return jq(fields[j]);
            }
        }
        return null;
    };

    // Text is only changed when it differs, as every change to the page wakes the observer below, which would
    // otherwise run again without end
    var setText = function(element, text) {
        if (element.text() !== text) {
            element.text(text);
        }
    };

    // Show how many characters each clinical history has used, and warn as the limit gets close
    var updateHistoryCounters = function() {
        getHistoryFields().each(function() {
            var field = jq(this);
            var counter = field.data('historyCounter');
            if (counter) {
                var length = field.val().length;
                var left = MAX_HISTORY_LENGTH - length;
                var hint = 'Up to ' + MAX_HISTORY_LENGTH + ' characters';
                if (left <= 0) {
                    hint = 'Limit reached: no more text can be added';
                }
                else if (left <= HISTORY_WARNING_LEFT) {
                    hint = left + (left === 1 ? ' character' : ' characters') + ' left';
                }
                setText(counter.find('.history-counter-hint'), hint);
                setText(counter.find('.history-counter-count'), length + ' / ' + MAX_HISTORY_LENGTH);
                counter.toggleClass('history-counter-near', left > 0 && left <= HISTORY_WARNING_LEFT);
                counter.toggleClass('history-counter-full', left <= 0);
                field.toggleClass('history-field-full', left <= 0);
            }
        });
    };

    // Clinical history is kept on one line, and never longer than the limit, even if the browser lets more through:
    // line breaks in pasted text become spaces
    var cleanHistoryText = function(textarea) {
        var value = textarea.value;
        var cleaned = value.replace(/[\r\n]+/g, ' ');
        if (cleaned.length > MAX_HISTORY_LENGTH) {
            cleaned = cleaned.substring(0, MAX_HISTORY_LENGTH);
        }
        if (cleaned !== value) {
            var caret = Math.min(textarea.selectionStart || cleaned.length, cleaned.length);
            textarea.value = cleaned;
            textarea.setSelectionRange(caret, caret);
        }
    };

    var addSameHistoryCheckbox = function(textarea) {
        var field = jq(textarea);
        if (field.data('sameHistoryReady')) {
            return false;
        }
        field.data('sameHistoryReady', true);

        // The browser stops typing and pasting beyond the limit
        field.attr('maxlength', MAX_HISTORY_LENGTH).addClass('history-field');
        var counter = jq('<div class="history-counter"><span class="history-counter-hint"></span>'
            + '<span class="history-counter-count"></span></div>');
        field.after(counter);
        field.data('historyCounter', counter);

        var checkbox = jq('<input type="checkbox" class="same-history-checkbox"/>');
        var wrapper = jq('<label class="same-history-option"></label>')
            .append(checkbox)
            .append(' Similar clinical history');
        counter.after(wrapper);

        checkbox.change(function() {
            if (this.checked) {
                if (jq.trim(field.val()) === '') {
                    // Empty test: copy the history from another test, and follow it while ticked
                    var source = findHistoryToCopy(field);
                    if (source === null) {
                        alert('Enter the clinical history in one of the tests first.');
                        this.checked = false;
                        return;
                    }
                    field.val(source.val());
                    field.data('copiedFrom', source);
                    field.data('copiedText', source.val());
                }
                else {
                    // Test with a history: share it with all the other tests that are still empty
                    jq('.same-history-checkbox').not(this).filter(function() {
                        return !jq(this).closest('.order-field-widget').find('textarea').data('copiedFrom');
                    }).prop('checked', false);
                    sharedHistory = field.val();
                    applySharedHistory();
                }
            }
            else {
                if (field.data('copiedFrom')) {
                    // Remove the copied text, unless the doctor has changed it since
                    if (field.val() === field.data('copiedText')) {
                        field.val('');
                    }
                    field.removeData('copiedFrom');
                    field.removeData('copiedText');
                }
                else {
                    sharedHistory = null;
                }
            }
            updateHistoryCounters();
        });

        // The Enter key does not start a new line in the clinical history
        field.on('keydown', function(e) {
            if (e.key === 'Enter' || e.keyCode === 13) {
                e.preventDefault();
            }
        });

        field.on('input', function() {
            cleanHistoryText(this);
            // Keep the other tests in step while the source text is edited
            if (checkbox.is(':checked') && !field.data('copiedFrom')) {
                var previous = sharedHistory;
                sharedHistory = field.val();
                applySharedHistory(previous);
            }
            // Update tests that copied from this one and have not been changed since
            getHistoryFields().each(function() {
                var other = jq(this);
                var copiedFrom = other.data('copiedFrom');
                if (copiedFrom && copiedFrom[0] === field[0] && other.val() === other.data('copiedText')) {
                    other.val(field.val());
                    other.data('copiedText', field.val());
                }
            });
            field.closest('.order-field-widget').find('.clinical-history-error').remove();
            updateHistoryCounters();
        });

        // A test added after a history was shared starts with that history
        if (sharedHistory !== null && jq.trim(field.val()) === '') {
            field.val(sharedHistory);
        }
        return true;
    };

    // Only does something when a test was added, so changes the script itself makes to the page are ignored
    var decorateHistoryFields = function() {
        var added = false;
        getHistoryFields().each(function() {
            added = addSameHistoryCheckbox(this) || added;
        });
        if (added) {
            updateHistoryCounters();
        }
    };

    decorateHistoryFields();
    // Tests are added to the page by the order widget when the doctor clicks to add one
    if (window.MutationObserver) {
        new MutationObserver(decorateHistoryFields).observe(document.body, { childList: true, subtree: true });
    }

    // Clinical history is required for every test being ordered, and cannot be longer than the limit
    var validateClinicalHistory = function() {
        var missing = [];
        var tooLong = false;
        getHistoryFields().each(function() {
            var field = jq(this);
            var orderForm = getOrderForm(field);
            var concept = orderForm.find('.order-field-widget.order-concept select').val();
            var action = orderForm.find('.order-field.order-action select').val();
            var widget = field.closest('.order-field-widget');
            widget.find('.clinical-history-error').remove();
            if (concept && action !== 'DISCONTINUE' && jq.trim(field.val()) === '') {
                widget.append('<span class="error clinical-history-error">Clinical history is required</span>');
                missing.push(field);
            }
            else if (concept && action !== 'DISCONTINUE' && field.val().length > MAX_HISTORY_LENGTH) {
                widget.append('<span class="error clinical-history-error">Clinical history cannot be longer than '
                    + MAX_HISTORY_LENGTH + ' characters</span>');
                missing.push(field);
                tooLong = true;
            }
        });
        if (missing.length > 0) {
            // Open the section holding the first missing field so the doctor can see it
            var content = missing[0].closest('.collapsible-content');
            if (!content.is(':visible')) {
                content.prev('.sectionHeader').addClass('expanded');
                content.show();
            }
            missing[0].focus();
            alert(tooLong ? 'Clinical history must be filled in for every test, and be no longer than '
                + MAX_HISTORY_LENGTH + ' characters.' : 'Clinical history is required for every test ordered.');
            return false;
        }
        return true;
    };

    if (typeof htmlForm !== 'undefined' && htmlForm.getBeforeSubmit) {
        htmlForm.getBeforeSubmit().push(validateClinicalHistory);
    }
    else if (typeof beforeSubmit !== 'undefined') {
        beforeSubmit.push(validateClinicalHistory);
    }
});
